      description: "Dạng tổng quát: $ax + by < c, ax + by \\le c, ax + by > c, ax + by \\ge c$ với $a^2 + b^2 \\ne 0$. Cặp $(x_0; y_0)$ là một nghiệm nếu khi thay vào cho khẳng định đúng.",
