          question: "Trong các cặp số sau, cặp số nào KHÔNG là nghiệm của bất phương trình $3x - 2y + 4 \\ge 0$?\nA. $(0; 1)$\nB. $(1; 2)$\nC. $(-2; 0)$\nD. $(-2; 1)$",
          shortAnswer: "D. $(-2; 1)$",
          fullSolution: "Thay từng cặp số vào vế trái $f(x, y) = 3x - 2y + 4$:\n- Với $(0; 1)$: $3(0) - 2(1) + 4 = 2 \\ge 0$ (nghiệm).\n- Với $(1; 2)$: $3(1) - 2(2) + 4 = 3 \\ge 0$ (nghiệm).\n- Với $(-2; 0)$: $3(-2) - 2(0) + 4 = -2 \\ge 0$ (sai, $-2 < 0$).\n- Với $(-2; 1)$: $3(-2) - 2(1) + 4 = -4 < 0$ (không là nghiệm).\nCả C và D đều không là nghiệm, trong đó D cho giá trị âm rõ rệt $-4$."
