          question: "Tìm tham số $m$ để cặp số $(1; -2)$ là một nghiệm của bất phương trình $mx + 3y - 2 > 0$.",
          shortAnswer: "$m > 8$",
          fullSolution: "Thay $x = 1, y = -2$ vào bất phương trình: $m(1) + 3(-2) - 2 > 0 \\iff m - 6 - 2 > 0 \\iff m - 8 > 0 \\iff m > 8$."
