          question: "Đường thẳng bờ của miền nghiệm bất phương trình $x + 2y - 4 \\le 0$ cắt hai trục toạ độ $Ox, Oy$ lần lượt tại hai điểm nào?",
          shortAnswer: "$A(4; 0)$ và $B(0; 2)$",
