          levelClass: "bg-emerald-100 text-emerald-800",
          question: "Hãy mô tả miền nghiệm của bất phương trình $x - y < 0$. Miền nghiệm này có chứa điểm $M(1; 3)$ không?",
          shortAnswer: "Miền nghiệm là nửa mặt phẳng bờ $d: y = x$ chứa điểm $(0; 1)$; có chứa điểm $M(1; 3)$",
          fullSolution: "- Đường thẳng bờ $d: x - y = 0$ (tức đường phân giác góc phần tư thứ I và III).\n- Lấy điểm thử $(0; 1)$: $0 - 1 = -1 < 0$ (thỏa mãn). Vậy miền nghiệm là nửa mặt phẳng bờ $d$ chứa $(0; 1)$ (không kể bờ $d$).\n- Kiểm tra điểm $M(1; 3)$: $1 - 3 = -2 < 0$ (đúng). Vậy miền nghiệm có chứa điểm $M(1; 3)$."
