          question: "Một học sinh có $50\\,000$ đồng để mua vở giá $7\\,000$ đồng/cuốn và bút giá $4\\,000$ đồng/cây. Gọi $x, y$ lần lượt là số vở và số bút mua được. Thiết lập bất phương trình biểu thị số tiền chi tiêu.",
