          fullSolution: "Tổng số tiền mua $x$ cuốn vở và $y$ cây bút là $7000x + 4000y$ đồng. Số tiền này không vượt quá $50\\,000$ đồng, do đó ta có bất phương trình: $7000x + 4000y \\le 50000 \\iff 7x + 4y \\le 50$."
