          shortAnswer: "$4x + 6y \\ge 60$ hay $2x + 3y \\ge 30$",
          fullSolution: "Số chỗ ngồi tổng cộng là $4x + 6y$. Để đủ ít nhất $60$ chỗ ngồi, ta có $4x + 6y \\ge 60 \\iff 2x + 3y \\ge 30$."
