          shortAnswer: "Không thể, vì tổng số giờ công cần là $115\\text{ giờ}$... à quên $3(25) + 2(20) = 115 \\le 120$ nên có thể sản xuất được!",
          fullSolution: "Bất phương trình số giờ công: $3x + 2y \\le 120$.\nVới $x = 25$ và $y = 20$, tổng thời gian cần là: $3(25) + 2(20) = 75 + 40 = 115\\text{ giờ}$.\nVì $115 \\le 120$, cơ sở hoàn toàn đủ thời gian công để sản xuất số lượng này."
