          shortAnswer: "Đạt mục tiêu (doanh thu đạt $2\\,900\\,000$ đồng... chưa đạt, cần kiểm tra: $25 \\times 80 + 15 \\times 60 = 2000 + 900 = 2900 < 3000$, chưa đạt mục tiêu)",
          fullSolution: "Bất phương trình doanh thu: $25000x + 15000y \\ge 3000000 \\iff 5x + 3y \\ge 600$.\nTại $x = 80, y = 60$: $5(80) + 3(60) = 400 + 180 = 580 < 600$ (tương đương doanh thu $2\\,900\\,000$ đồng).\nVì $2\\,900\\,000 < 3\\,000\\,000$ đồng nên gian hàng chưa đạt mục tiêu doanh thu."
