          shortAnswer: "$2x + y \\le 40$; đóng tối đa $12$ chiếc bàn",
          fullSolution: "Gọi $x$ là số bàn, $y$ là số ghế. Bất phương trình nguyên liệu gỗ là: $2x + y \\le 40$.\nKhi $y = 15$: $2x + 15 \\le 40 \\iff 2x \\le 25 \\iff x \\le 12{,}5$.\nVì số bàn $x$ là số tự nhiên nên số bàn tối đa có thể đóng là $12$ chiếc."
