      description: "Hệ gồm hai hay nhiều bất phương trình bậc nhất hai ẩn $x, y$. Cặp số $(x_0; y_0)$ là một nghiệm của hệ khi và chỉ khi nó là nghiệm của tất cả các bất phương trình trong hệ.",
