          question: "Hệ nào sau đây là hệ bất phương trình bậc nhất hai ẩn?\nA. $\\begin{cases} 2x + y \\le 3 \\\\ x - 3y > 1 \\end{cases}$\nB. $\\begin{cases} x^2 + y \\le 4 \\\\ 2x - y > 0 \\end{cases}$\nC. $\\begin{cases} 2x - yz \\le 1 \\\\ x + 3y \\ge 2 \\end{cases}$\nD. $\\begin{cases} \\frac{1}{x} + y > 2 \\\\ 3x - y \\le 5 \\end{cases}$",
          shortAnswer: "A. $\\begin{cases} 2x + y \\le 3 \\\\ x - 3y > 1 \\end{cases}$",
          fullSolution: "Hệ bất phương trình bậc nhất hai ẩn là hệ gồm các bất phương trình mà mỗi bất phương trình đều là bất phương trình bậc nhất hai ẩn. Do đó chỉ có hệ A thỏa mãn."
