          question: "Một dốc nghiêng tạo với mặt đất nằm ngang một góc $\\alpha = 30^\\circ$. Tính sin của góc dốc này.",
          shortAnswer: "$\\frac{1}{2}$",
          fullSolution: "Ta có $\\sin 30^\\circ = \\frac{1}{2}$."
