          question: "Hai góc bù nhau có tổng số đo bằng bao nhiêu độ?",
          shortAnswer: "$180^\\circ$",
          fullSolution: "Theo định nghĩa hình học, hai góc bù nhau là hai góc có tổng số đo bằng $180^\\circ$."
