          question: "Cho hình lục giác đều $ABCDEF$ có cạnh bằng $2\\text{ cm}$. Gọi $O$ là tâm của lục giác đều. Tính độ dài của vectơ $\\vec{AD}$ và vectơ $\\vec{AC}$.",
