          fullSolution: "- $AD$ là đường chéo chính đi qua tâm $O$ nên $AD = 2OA = 2 \\times 2 = 4\\text{ cm} \\implies |\\vec{AD}| = 4\\text{ cm}$.\n- Tam giác $ABC$ cân tại $B$ có $AB = BC = 2\\text{ cm}$ và góc $\\widehat{ABC} = 120^\\circ$. Áp dụng định lí côsin:\n$AC^2 = 2^2 + 2^2 - 2 \\cdot 2 \\cdot 2 \\cdot \\cos 120^\\circ = 4 + 4 - 8 \\cdot \\left(-\\frac{1}{2}\\right) = 8 + 4 = 12$.\nSuy ra $AC = \\sqrt{12} = 2\\sqrt{3}\\text{ cm} \\implies |\\vec{AC}| = 2\\sqrt{3}\\text{ cm}$."
