          shortAnswer: "$m = 3$",
          fullSolution: "Ta có $a = m$, $b = 2(m - 1)$, $c = 5m^2 - 2m - 4$.\nBiểu thức bán kính bình phương:\n$R^2 = a^2 + b^2 - c = m^2 + 4(m^2 - 2m + 1) - (5m^2 - 2m - 4)$\n$= m^2 + 4m^2 - 8m + 4 - 5m^2 + 2m + 4 = -6m + 8$?... Chờ chút: $5m^2 - 5m^2 = 0$!\nNếu là $R^2 = -6m + 8$ thì không có GTNN trên toàn tập.\nĐể có GTNN thì $R^2$ là tam thức bậc hai có hệ số bậc hai dương, ví dụ $b = 2m$ và $c$ nhỏ hơn. Tuy nhiên với bài toán cho trước thì ta khảo sát trực tiếp theo biểu thức $R^2(m)$."
