          shortAnswer: "$x + \\sqrt{3}y - 4 = 0$ và $x - \\sqrt{3}y - 4 = 0$",
          fullSolution: "Đường tròn có tâm $O(0; 0)$ và bán kính $R = 2$. Khoảng cách $OA = 4 > R = 2$ nên $A$ nằm ngoài đường tròn.\nĐường thẳng $\\Delta$ đi qua $A(4; 0)$ có VTPT $\\vec{n} = (a; b)$ ($a^2 + b^2 \\ne 0$) có dạng:\n$a(x - 4) + by = 0 \\iff ax + by - 4a = 0$.\nĐiều kiện tiếp xúc $d(O, \\Delta) = R$:\n$\\frac{|-4a|}{\\sqrt{a^2 + b^2}} = 2 \\iff 4|a| = 2\\sqrt{a^2 + b^2} \\iff 2|a| = \\sqrt{a^2 + b^2}$.\nBình phương hai vế:\n$4a^2 = a^2 + b^2 \\iff 3a^2 = b^2 \\iff b = \\pm a\\sqrt{3}$.\nChọn $a = 1 \\implies b = \\sqrt{3}$ hoặc $b = -\\sqrt{3}$.\nVậy hai tiếp tuyến là: $x + \\sqrt{3}y - 4 = 0$ và $x - \\sqrt{3}y - 4 = 0$."
